        if(op==51){int64_t n=integer(b);if(n<0||(uint64_t)n>=a->length)bounds();ApxValue *out=apx_array_new((int64_t)a->length);memcpy(out->items,a->items,a->length*sizeof *out->items);out->items[n]=c;return out;}
