    bound.rlim_cur=bound.rlim_max=8u*1024u*1024u;limits_ok=limits_ok&&setrlimit(RLIMIT_STACK,&bound)==0;
    bound.rlim_cur=bound.rlim_max=32u*1024u*1024u;limits_ok=limits_ok&&setrlimit(RLIMIT_FSIZE,&bound)==0;
    bound.rlim_cur=bound.rlim_max=0;limits_ok=limits_ok&&setrlimit(RLIMIT_CORE,&bound)==0;
    const char *channel=getenv("APX_HOST_FD");
